data class Discipline(val id:Long,val name:String,val color:Long)
data class Slot(val id:Long,val disciplineId:Long,val day:Int,val start:String,val end:String,val alarm:Boolean)
data class Log(val id:Long,val disciplineId:Long,val date:String,val minutes:Int)
data class Store(val disciplines:List<Discipline>,val slots:List<Slot>,val logs:List<Log>)

private val Blue=Color(0xFF087DF0); private val Navy=Color(0xFF112544); private val Bg=Color(0xFFF5F8FD); private val Red=Color(0xFFFF416C); private val Green=Color(0xFF10B981)
private val colors=listOf(0xFF1684EAL,0xFFFF426DL,0xFFF9B51AL,0xFF10B981L,0xFF7C5CE7L,0xFFFF7A32L)
private val days=listOf("Seg","Ter","Qua","Qui","Sex","Sáb","Dom")

class MainActivity:ComponentActivity(){
 private val notifications=registerForActivityResult(ActivityResultContracts.RequestPermission()){}
 override fun onCreate(b:Bundle?){super.onCreate(b);createChannel();if(Build.VERSION.SDK_INT>=33)notifications.launch(Manifest.permission.POST_NOTIFICATIONS);setContent{MaterialTheme(colorScheme=lightColorScheme(primary=Blue,background=Bg)){App(this)}}}
 private fun createChannel(){if(Build.VERSION.SDK_INT>=26)getSystemService(NotificationManager::class.java).createNotificationChannel(NotificationChannel("alarm","Alarmes de estudo",NotificationManager.IMPORTANCE_HIGH).apply{enableVibration(true);lockscreenVisibility=Notification.VISIBILITY_PUBLIC})}
}

private fun load(c:Context):Store=runCatching{val root=JSONObject(c.getSharedPreferences("cronos_172",0).getString("data","{}")?:"{}");val da=root.optJSONArray("disciplines")?:JSONArray();val sa=root.optJSONArray("slots")?:JSONArray();val la=root.optJSONArray("logs")?:JSONArray();Store(List(da.length()){i->da.getJSONObject(i).let{Discipline(it.getLong("id"),it.getString("name"),it.getLong("color"))}},List(sa.length()){i->sa.getJSONObject(i).let{Slot(it.getLong("id"),it.getLong("disciplineId"),it.getInt("day"),it.getString("start"),it.getString("end"),it.optBoolean("alarm",true))}},List(la.length()){i->la.getJSONObject(i).let{Log(it.getLong("id"),it.getLong("disciplineId"),it.getString("date"),it.getInt("minutes"))}})}.getOrDefault(Store(emptyList(),emptyList(),emptyList()))
private fun save(c:Context,s:Store){val d=JSONArray();s.disciplines.forEach{d.put(JSONObject().put("id",it.id).put("name",it.name).put("color",it.color))};val a=JSONArray();s.slots.forEach{a.put(JSONObject().put("id",it.id).put("disciplineId",it.disciplineId).put("day",it.day).put("start",it.start).put("end",it.end).put("alarm",it.alarm))};val l=JSONArray();s.logs.forEach{l.put(JSONObject().put("id",it.id).put("disciplineId",it.disciplineId).put("date",it.date).put("minutes",it.minutes))};c.getSharedPreferences("cronos_172",0).edit().putString("data",JSONObject().put("disciplines",d).put("slots",a).put("logs",l).toString()).apply()}

private fun schedule(c:Context,slot:Slot,name:String){if(!slot.alarm)return;val am=c.getSystemService(AlarmManager::class.java);if(Build.VERSION.SDK_INT>=31&&!am.canScheduleExactAlarms()){c.startActivity(Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));return};val now=ZonedDateTime.now();val t=LocalTime.parse(slot.start);var at:ZonedDateTime?=null;for(n in 0..7){val date=now.toLocalDate().plusDays(n.toLong());val candidate=ZonedDateTime.of(date,t,now.zone);if(date.dayOfWeek.value==slot.day&&candidate.isAfter(now)){at=candidate;break}};at?:return;val p=PendingIntent.getBroadcast(c,slot.id.toInt(),Intent(c,AlarmReceiver::class.java).putExtra("subject",name),PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE);am.setAlarmClock(AlarmManager.AlarmClockInfo(at.toInstant().toEpochMilli(),p),p)}

@Composable private fun App(c:Context){var store by remember{mutableStateOf(load(c))};var tab by remember{mutableIntStateOf(0)};var selected by remember{mutableStateOf<Discipline?>(null)};var newD by remember{mutableStateOf(false)};var selectedSlot by remember{mutableStateOf<Slot?>(null)}
 fun update(s:Store){store=s;save(c,s)}
 Scaffold(containerColor=Bg,bottomBar={NavigationBar(containerColor=Color.White){listOf(Triple("Disciplinas",Icons.Default.School,0),Triple("Agenda",Icons.Default.CalendarMonth,1),Triple("Cronómetro",Icons.Default.Timer,2),Triple("Análise",Icons.Default.BarChart,3),Triple("Definições",Icons.Default.Settings,4)).forEach{x->NavigationBarItem(tab==x.third,{tab=x.third;selected=null},{Icon(x.second,null)},{Text(x.first,fontSize=9.sp)})}}},floatingActionButton={if(tab==0&&selected==null)FloatingActionButton({newD=true},containerColor=Blue){Icon(Icons.Default.Add,null,tint=Color.White)}}){pad->Box(Modifier.padding(pad).fillMaxSize()){when(tab){0->if(selected==null)Disciplines(store){selected=it}else Detail(selected!!,store,{selected=null},{slot->update(store.copy(slots=store.slots+slot));schedule(c,slot,selected!!.name)},{slot->update(store.copy(slots=store.slots.filterNot{it.id==slot.id}))},{d->update(Store(store.disciplines.filterNot{it.id==d.id},store.slots.filterNot{it.disciplineId==d.id},store.logs.filterNot{it.disciplineId==d.id}));selected=null});1->Agenda(store){selectedSlot=it};2->Timer(c,store.disciplines){id,min->update(store.copy(logs=store.logs+Log(System.nanoTime(),id,LocalDate.now().toString(),min)))};3->Analysis(store);else->SettingsPage(c)}}}
 if(newD)DisciplineDialog({newD=false}){name->update(store.copy(disciplines=store.disciplines+Discipline(System.currentTimeMillis(),name,colors[store.disciplines.size%colors.size])));newD=false}
 selectedSlot?.let{slot->StudyDialog(store.disciplines.firstOrNull{it.id==slot.disciplineId}?.name?:"Disciplina",{selectedSlot=null},{minutes->update(store.copy(logs=store.logs+Log(System.nanoTime(),slot.disciplineId,LocalDate.now().toString(),minutes)));selectedSlot=null},{update(store.copy(slots=store.slots.filterNot{it.id==slot.id}));selectedSlot=null})}
}

@Composable private fun Header(title:String,back:(()->Unit)?=null){Row(Modifier.fillMaxWidth().height(64.dp).background(Color(0xFFF8FAFE)).padding(horizontal=12.dp),verticalAlignment=Alignment.CenterVertically){if(back!=null)IconButton(back){Icon(Icons.Default.ArrowBack,null,tint=Navy)};Text(title,Modifier.weight(1f),fontSize=22.sp,fontWeight=FontWeight.Bold,color=Navy);if(back==null)IconButton({}){Icon(Icons.Default.Search,null,tint=Navy)};Surface(shape=RoundedCornerShape(10.dp),color=Blue){Icon(Icons.Default.Add,null,tint=Color.White,modifier=Modifier.padding(7.dp).size(20.dp))}}}
@Composable private fun Disciplines(s:Store,open:(Discipline)->Unit){Column(Modifier.fillMaxSize().background(Bg)){Header("Disciplinas");LazyColumn(Modifier.weight(1f),contentPadding=PaddingValues(top=8.dp,bottom=8.dp)){items(s.disciplines,key={it.id}){d->Card(Modifier.fillMaxWidth().padding(horizontal=14.dp,vertical=5.dp).clickable{open(d)},colors=CardDefaults.cardColors(Color.White),shape=RoundedCornerShape(14.dp),elevation=CardDefaults.cardElevation(1.dp)){Row(Modifier.padding(12.dp),verticalAlignment=Alignment.CenterVertically){Surface(Modifier.size(54.dp),shape=RoundedCornerShape(13.dp),color=Color(d.color)){Icon(Icons.Default.Functions,null,tint=Color.White,modifier=Modifier.padding(12.dp))};Column(Modifier.padding(start=12.dp).weight(1f)){Text(d.name,fontWeight=FontWeight.Bold,color=Navy,fontSize=16.sp);Text("${label(s.logs.filter{it.disciplineId==d.id}.sumOf{it.minutes})} estudados",fontSize=12.sp,color=Color(0xFF53657D));Text("${s.slots.count{it.disciplineId==d.id}} programações",fontSize=12.sp,color=Color(0xFF53657D))};Icon(Icons.Default.ChevronRight,null,tint=Color(0xFF50627A))}}};item{Button({},Modifier.fillMaxWidth().padding(14.dp).height(52.dp),shape=RoundedCornerShape(10.dp)){Icon(Icons.Default.Add,null);Text("  Nova disciplina",fontWeight=FontWeight.Bold)}}}}}
@Composable private fun Detail(d:Discipline,s:Store,back:()->Unit,add:(Slot)->Unit,remove:(Slot)->Unit,delete:(Discipline)->Unit){var showAdd by remember{mutableStateOf(false)};val own=s.slots.filter{it.disciplineId==d.id};Column{Header(d.name,back);Card(Modifier.fillMaxWidth().padding(14.dp),colors=CardDefaults.cardColors(Color(d.color))){Column(Modifier.padding(18.dp)){Text(d.name,color=Color.White,fontSize=22.sp,fontWeight=FontWeight.Bold);Text("${label(s.logs.filter{it.disciplineId==d.id}.sumOf{it.minutes})} estudados",color=Color.White)}};Text("Programações",Modifier.padding(16.dp),fontWeight=FontWeight.Bold);LazyColumn(Modifier.weight(1f)){items(own,key={it.id}){x->Card(Modifier.fillMaxWidth().padding(14.dp,5.dp),colors=CardDefaults.cardColors(Color.White)){Row(Modifier.padding(14.dp),verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.Alarm,null,tint=Color(d.color));Column(Modifier.padding(start=12.dp).weight(1f)){Text(days[x.day-1],fontWeight=FontWeight.Bold);Text("${x.start} - ${x.end}")};IconButton({remove(x)}){Icon(Icons.Default.Delete,null,tint=Red)}}}}};OutlinedButton({showAdd=true},Modifier.fillMaxWidth().padding(14.dp)){Icon(Icons.Default.Add,null);Text(" Adicionar programação")};Button({delete(d)},Modifier.fillMaxWidth().padding(horizontal=14.dp),colors=ButtonDefaults.buttonColors(containerColor=Color(0xFFFFE9EE),contentColor=Red)){Text("Eliminar esta disciplina")}}
 if(showAdd)SlotDialog(d,{showAdd=false}){add(it);showAdd=false}}

@Composable private fun Agenda(s:Store,open:(Slot)->Unit){var mode by remember{mutableIntStateOf(1)};var offset by remember{mutableIntStateOf(0)};val monday=LocalDate.now().minusDays((LocalDate.now().dayOfWeek.value-1).toLong()).plusWeeks(offset.toLong());Column{Header("Agenda");Row(Modifier.fillMaxWidth().padding(12.dp)){listOf("Dia","Semana","Mês").forEachIndexed{i,t->Button({mode=i},Modifier.weight(1f).padding(2.dp),colors=ButtonDefaults.buttonColors(containerColor=if(mode==i)Blue else Color(0xFFE8EEF7),contentColor=if(mode==i)Color.White else Navy)){Text(t)}}};Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){IconButton({offset--}){Icon(Icons.Default.ChevronLeft,null)};Text("${monday.dayOfMonth} – ${monday.plusDays(6).format(DateTimeFormatter.ofPattern("d 'de' MMMM 'de' yyyy"))}",Modifier.weight(1f),textAlign=TextAlign.Center,fontWeight=FontWeight.Bold);IconButton({offset++}){Icon(Icons.Default.ChevronRight,null)}};if(mode==1)Week(s,monday,open)else Day(s,if(mode==0)LocalDate.now().dayOfWeek.value else 1,open)}}
@Composable private fun Week(s:Store,monday:LocalDate,open:(Slot)->Unit){Row(Modifier.fillMaxSize().padding(6.dp)){(1..7).forEach{day->Column(Modifier.weight(1f)){Text(days[day-1],Modifier.fillMaxWidth(),textAlign=TextAlign.Center,fontSize=9.sp);Text(monday.plusDays((day-1).toLong()).dayOfMonth.toString(),Modifier.fillMaxWidth(),textAlign=TextAlign.Center,fontWeight=FontWeight.Bold);s.slots.filter{it.day==day}.sortedBy{it.start}.forEach{x->val d=s.disciplines.firstOrNull{it.id==x.disciplineId};Card(Modifier.fillMaxWidth().padding(1.dp).clickable{open(x)},colors=CardDefaults.cardColors(Color(d?.color?:colors.first()).copy(alpha=.2f))){Text("${(d?.name?:"").take(4)}\n${x.start}",fontSize=8.sp,modifier=Modifier.padding(3.dp))}}}}}
@Composable private fun Day(s:Store,day:Int,open:(Slot)->Unit){LazyColumn{items(s.slots.filter{it.day==day}.sortedBy{it.start}){x->val d=s.disciplines.firstOrNull{it.id==x.disciplineId};Card(Modifier.fillMaxWidth().padding(12.dp,5.dp).clickable{open(x)},colors=CardDefaults.cardColors(Color.White)){Row(Modifier.padding(14.dp)){Text("${x.start}\n${x.end}",Modifier.width(80.dp));Text(d?.name?:"Disciplina",fontWeight=FontWeight.Bold)}}}}}

@Composable private fun Timer(c:Context,ds:List<Discipline>,finish:(Long,Int)->Unit){val p=c.getSharedPreferences("timer_172",0);var selectedId by remember{mutableLongStateOf(p.getLong("discipline",ds.firstOrNull()?.id?:0L))};var running by remember{mutableStateOf(p.getBoolean("running",false))};var base by remember{mutableLongStateOf(p.getLong("base",0L))};var started by remember{mutableLongStateOf(p.getLong("started",0L))};var now by remember{mutableLongStateOf(System.currentTimeMillis())};LaunchedEffect(running){while(running){now=System.currentTimeMillis();delay(500)}};val seconds=base+if(running)((now-started)/1000).coerceAtLeast(0)else 0;Column(horizontalAlignment=Alignment.CenterHorizontally){Header("Cronómetro");var expanded by remember{mutableStateOf(false)};Box{OutlinedButton({expanded=true}){Text(ds.firstOrNull{it.id==selectedId}?.name?:"Selecionar disciplina")};DropdownMenu(expanded,{expanded=false}){ds.forEach{d->DropdownMenuItem({Text(d.name)},{selectedId=d.id;p.edit().putLong("discipline",d.id).apply();expanded=false})}}};Box(Modifier.padding(28.dp).size(230.dp).background(Color(0xFFEAF3FF),CircleShape),contentAlignment=Alignment.Center){Column(horizontalAlignment=Alignment.CenterHorizontally){Text("%02d:%02d:%02d".format(seconds/3600,(seconds/60)%60,seconds%60),fontSize=38.sp,fontWeight=FontWeight.Bold,color=Navy);Text(if(running)"A estudar" else "Pronto para estudar")}};Row(horizontalArrangement=Arrangement.spacedBy(10.dp)){Button({if(running){base=seconds;running=false;p.edit().putLong("base",base).putBoolean("running",false).apply()}else{started=System.currentTimeMillis();now=started;running=true;p.edit().putLong("started",started).putBoolean("running",true).apply()}},colors=ButtonDefaults.buttonColors(containerColor=Blue)){Text(if(running)"Pausar" else "Iniciar")};OutlinedButton({if(selectedId!=0L&&seconds>0){finish(selectedId,(seconds/60).toInt().coerceAtLeast(1));base=0;running=false;p.edit().clear().apply()}}){Text("Terminar")}};Row(Modifier.padding(16.dp),horizontalArrangement=Arrangement.spacedBy(8.dp)){listOf(5,15,30).forEach{m->AssistChip({base+=m*60;p.edit().putLong("base",base).apply()},{Text("+$m min")})}}}}

@Composable private fun Analysis(s:Store){val total=s.logs.sumOf{it.minutes};Column{Header("Análise");Row{Stat("Tempo total",label(total),Modifier.weight(1f));Stat("Média diária",label(total/7),Modifier.weight(1f))};Text("Tempo por disciplina",Modifier.padding(16.dp),fontWeight=FontWeight.Bold);LazyColumn{items(s.disciplines){d->val m=s.logs.filter{it.disciplineId==d.id}.sumOf{it.minutes};ListItem(headlineContent={Text(d.name)},supportingContent={LinearProgressIndicator(progress={if(total==0)0f else m.toFloat()/total},color=Color(d.color))},trailingContent={Text(label(m))})}}}}
@Composable private fun Stat(t:String,v:String,m:Modifier){Card(m.padding(7.dp),colors=CardDefaults.cardColors(Color.White),shape=RoundedCornerShape(14.dp),elevation=CardDefaults.cardElevation(1.dp)){Column(Modifier.padding(14.dp)){Icon(if(t.contains("Média"))Icons.Default.BarChart else Icons.Default.Schedule,null,tint=Blue);Text(t,color=Color(0xFF53657D),fontSize=12.sp,modifier=Modifier.padding(top=8.dp));Text(v,fontSize=22.sp,fontWeight=FontWeight.Bold,color=Navy)}}}
