@Composable private fun DisciplineDialog(close:()->Unit,save:(String)->Unit){var name by remember{mutableStateOf("")};AlertDialog(onDismissRequest=close,title={Text("Nova disciplina")},text={OutlinedTextField(name,{name=it},label={Text("Nome da disciplina")})},confirmButton={Button({if(name.isNotBlank())save(name.trim())}){Text("Guardar")}},dismissButton={TextButton(close){Text("Cancelar")}})}
@Composable private fun SlotDialog(d:Discipline,close:()->Unit,save:(Slot)->Unit){var day by remember{mutableIntStateOf(1)};var start by remember{mutableStateOf("18:00")};var end by remember{mutableStateOf("19:00")};var alarm by remember{mutableStateOf(true)};var error by remember{mutableStateOf("")};AlertDialog(onDismissRequest=close,title={Text("Adicionar programação")},text={Column{Row{(1..7).forEach{i->FilterChip(day==i,{day=i},{Text(days[i-1].take(1))},modifier=Modifier.weight(1f))}};OutlinedTextField(start,{start=it},label={Text("Início")});OutlinedTextField(end,{end=it},label={Text("Fim")});Row(verticalAlignment=Alignment.CenterVertically){Text("Alarme",Modifier.weight(1f));Switch(alarm,{alarm=it})};if(error.isNotEmpty())Text(error,color=Red)}},confirmButton={Button({runCatching{val a=LocalTime.parse(start);val b=LocalTime.parse(end);require(b.isAfter(a));save(Slot(System.nanoTime(),d.id,day,a.toString(),b.toString(),alarm))}.onFailure{error="Horário inválido."}}){Text("Guardar")}},dismissButton={TextButton(close){Text("Cancelar")}})}
@Composable private fun StudyDialog(name:String,close:()->Unit,save:(Int)->Unit,delete:()->Unit){var h by remember{mutableStateOf("")};var m by remember{mutableStateOf("")};var error by remember{mutableStateOf("")};AlertDialog(onDismissRequest=close,title={Text(name)},text={Column{Text("Quanto tempo estudou?",fontWeight=FontWeight.Bold);Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){OutlinedTextField(h,{h=it.filter(Char::isDigit)},Modifier.weight(1f),label={Text("Horas")});OutlinedTextField(m,{m=it.filter(Char::isDigit)},Modifier.weight(1f),label={Text("Minutos")})};Button({val total=(h.toIntOrNull()?:0)*60+(m.toIntOrNull()?:0);if(total>0)save(total)else error="Indique o tempo estudado."},Modifier.fillMaxWidth().padding(top=10.dp)){Text("Guardar tempo estudado")};TextButton(delete,Modifier.fillMaxWidth()){Text("Eliminar apenas esta programação",color=Red)};if(error.isNotEmpty())Text(error,color=Red)}},confirmButton={},dismissButton={TextButton(close){Text("Fechar")}})}
private fun label(m:Int)=if(m>=60)"${m/60}h ${m%60}min" else "${m}min"
